import { ChannelType, } from '../../../api/create-cart/index.js';
import { BOOKING_APP_ID } from '../../constants.js';
export function buildCartRequest(params) {
    return {
        catalogItems: params.bookingIds.map((id) => buildCatalogItem(id, params.appId)),
        cart: buildCartShape(params),
    };
}
function buildCatalogItem(bookingId, appId) {
    return {
        quantity: 1,
        catalogReference: {
            catalogItemId: bookingId,
            appId: appId ?? BOOKING_APP_ID,
        },
    };
}
function buildCartShape(params) {
    const { contactDetails, businessLocationId } = params;
    const cart = {
        source: { channelType: ChannelType.WEB },
    };
    if (businessLocationId) {
        cart.businessInfo = { locationId: businessLocationId };
    }
    if (contactDetails) {
        cart.customerInfo = {
            ...(contactDetails.firstName
                ? { firstName: contactDetails.firstName }
                : {}),
            ...(contactDetails.lastName ? { lastName: contactDetails.lastName } : {}),
            ...(contactDetails.phone ? { phone: contactDetails.phone } : {}),
            ...(contactDetails.email ? { email: contactDetails.email } : {}),
        };
        if (contactDetails.fullAddress?.country) {
            cart.deliveryInfo = { address: { ...contactDetails.fullAddress } };
            cart.paymentInfo = {
                billingAddress: { ...contactDetails.fullAddress },
            };
        }
    }
    return cart;
}
